(() => {
'use strict';
const D=window.LIFE_DATA,G=window.CISHENG_GAME;
if(!D?.years?.length||!G)return;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],A=v=>Array.isArray(v)?v:[],E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const isPrivatePreview=()=>window.BIOGRAPHY_DATA?.meta?.publication==='private-preview';
const data=()=>window.BIOGRAPHY_DATA||{meta:{title:'此生',subtitle:'个人记录正在整理',cutoff:'2026-11-06',publication:'private-preview'},years:{},sources:[],threads:[]};
const years=D.years.map(y=>y.year),valid=v=>years.includes(Number(v)),min=years[0],max=years.at(-1),BOOKMARK='cisheng-private-biography-reader-v1';
const labels={recorded:'有个人记录',gap:'记忆缺口',present:'当下进行中',projection:'未来推演'},sceneLabels={documented:'据本人记录叙写·含叙事连接',reconstructed:'叙事补写',imagined:'情境推演'};
let bookmark=null;try{const saved=JSON.parse(localStorage.getItem(BOOKMARK)||'{}');if(valid(saved.year))bookmark=Number(saved.year);}catch(_){}
const state={year:bookmark??G.resumeYear()??2026,filter:'all',shelf:false,sourceIds:[]};
function rawYear(year){return D.years.find(y=>y.year===Number(year));}
function yearRecord(year){const b=data().years?.[year];if(b)return b;const future=Number(year)>Number((data().meta?.cutoff||'2026').slice(0,4));return{year:Number(year),mode:future?'projection':'gap',title:future?'这一页，尚待展开':'这一年的记录仍有留白',logline:future?'未来篇章正在整理，暂不补造具体经历。':'没有找到资料，不代表这一年没有故事。',opening:future?'这段人生还没有发生。这里将以已知背景和明确假设编写情境，保留变化与选择。':'当前预览尚未为这一年装载个人记录。已知之外的细节先保持空白，不用命盘或通用主题替你填写。',scenes:[],anchoredFacts:[],echoes:[],sourceIds:[],choices:[]};}
const sourceById=id=>A(data().sources).find(s=>String(s.id)===String(id));
function sourceButtons(ids,caption='查看来处'){const unique=[...new Set(A(ids).map(String))];return unique.length?`<button class="bio-source-link" data-bio-sources="${E(unique.join('|'))}">${E(caption)} <span>${unique.length}</span> ↗</button>`:'';}
function sourceType(type){return({chat:'本人对话',conversation:'本人对话',thread:'本人对话',doc:'本人文档',document:'本人文档',note:'本人记录',local:'本地记录',local_document:'本地文档',local_file:'本地文件',personal:'本人记录',first_person:'本人叙述',memory:'本人回忆',artifact:'交付产物',calendar:'个人日历',timeline:'个人时间线'})[type]||'个人资料';}
function certaintyLabel(value){
 const labels={documented:'资料记载',confirmed:'本人确认',verified:'已核对记录',high:'来源明确',medium:'单条记录支持',low:'仍有不确定',recalled:'本人回忆',reported:'本人叙述',uncertain:'尚待核对',single_source:'单条来源',corroborated:'多条记录支持',day:'日期明确的本人记录',month:'月份明确的本人记录',range:'阶段范围可确认','undated-recollection':'本人回忆，公历年未定',year:'年份明确的本人记录',academic_term:'学期范围的回顾',academic_year:'学年范围的回顾',approximate:'大致阶段，日期待核','dated-reflection':'有日期的当时反思','dated-self-statement':'有日期的本人表述',entry_date:'记录当日所述',holiday_range:'假期范围的本人记录','intention-not-event':'当时愿望，非已完成事件',month_inferred_from_academic_year:'根据学年推定月份',month_part:'月内阶段的本人记录',month_range:'月份范围的本人记录',month_range_in_profile:'个人简介所列月份范围',month_recounted_2024_04_18:'四月记录对三月的回顾',season:'季节范围的本人记录','self-report-year-context':'依据本人记录的年份语境'};
 if(!value)return'精度尚待补充';
 if(typeof value==='object'){const label=value.label;if(typeof label==='string'&&/[\u3400-\u9fff]/.test(label)&&!/[A-Za-z_]/.test(label))return label;return labels[value.status]||'精度尚待补充';}
 return labels[value]||'精度尚待补充';
}
function starBadge(type,prefix){return['禄','权','科','忌'].includes(type)?`<small class="mutation-badge mut-${E(type)}" title="${E(prefix)}化${E(type)}">${E(prefix)}${E(type)}</small>`:'';}
function renderStarReference(year){
 const y=rawYear(year);if(!y)return'';
 const layers=[{key:'natal',label:'本命命宫',palace:D.palaces.find(p=>p.name==='命宫'),scope:'原局',mutations:[]},{key:'decadal',label:(y.scopeName||'大限')+'命宫',palace:D.palaces.find(p=>p.name===y.decadalPalace),scope:`${y.decadalStem||''}${y.decadalBranch||''} · 叠本命${y.decadalPalace||'待核'}`,mutations:A(y.decadalMutations),prefix:y.scopeName||'大限'},{key:'annual',label:'所选流年命宫',palace:D.palaces.find(p=>p.name===y.annualPalace),scope:`${y.stem||''}${y.branch||''} · 叠本命${y.annualPalace||'待核'}`,mutations:A(y.annualMutations),prefix:'流年'}];
 return`<section class="bio-star-reference" aria-label="所选农历流年三层主星对照"><div class="bio-star-reference-heading"><h2>所选农历流年对照 <span>${y.year} · ${E(y.stem)}${E(y.branch)} · 虚岁${E(y.nominalAge)}</span></h2><button data-bio-comic-year="${y.year}">去漫画自查 ↗</button></div><div class="star-layers bio-star-layers">${layers.map(layer=>{const p=layer.palace;return`<div class="star-layer bio-star-layer"><div class="star-layer-label"><strong>${E(layer.label)}</strong><span>${E(layer.scope)}${p?` · ${E(p.stem)}${E(p.branch)}`:''}</span></div><div class="star-layer-stars">${p?A(p.major).length?A(p.major).map(star=>`<div class="main-star bio-star"><span>${E(star.name)}</span><small class="star-brightness">${E(star.brightness||'亮度未列')}</small><span class="bio-star-badges">${starBadge(star.mutagen,'生年')}${layer.mutations.filter(m=>m.star===star.name).map(m=>starBadge(m.type,layer.prefix)).join('')}</span></div>`).join(''):'<span class="bio-empty-stars">本宫无十四主星 · 不借星填入</span>':'<span class="bio-empty-stars">宫位资料待核 · 不填主星</span>'}</div></div>`;}).join('')}</div><p class="bio-star-reference-note">亮度取原局；生年与限年四化分标。对照范围：${E(y.startDate)} 至 ${E(y.endBefore)} 前一日，不把本页全部公历事件绑定于同一流年。</p></section>`;
}
const section=document.createElement('section');section.id='biography-screen';section.className='screen biography-screen';section.hidden=true;
section.innerHTML=`<div class="bio-private-bar"><span id="bio-publication-label"></span><span id="bio-cutoff"></span></div><div class="bio-reader-toolbar"><button id="bio-shelf-toggle" aria-controls="bio-bookshelf" aria-expanded="false">书架 <span>☰</span></button><button id="bio-return-cover">← 封面</button><span id="bio-reader-position"></span><button id="bio-to-comic">去漫画中演练 ↗</button><button id="bio-to-chart">命盘自查 ↗</button></div><div class="bio-book-layout"><aside class="bio-bookshelf" id="bio-bookshelf"><div class="bio-shelf-title"><span>A LIFE IN RECORDS / 个人传记</span><h2 id="bio-library-title">此生</h2><p id="bio-library-subtitle"></p></div><label class="bio-find-year">找一年<select id="bio-year-select" aria-label="选择传记年份"></select></label><div class="bio-shelf-filters" role="group" aria-label="书架筛选"><button data-bio-filter="all" class="active">全部年份</button><button data-bio-filter="recorded">有个人记录</button></div><div id="bio-volume-list"></div><div class="bio-shelf-foot"><span class="bio-mode-dot recorded"></span>有记录 <span class="bio-mode-dot gap"></span>留白 <span class="bio-mode-dot projection"></span>推演<p>按公历十年分册。命盘大限在自查中独立保留。</p></div></aside><article id="bio-article" class="bio-article" aria-live="polite"></article></div>`;
$('main').appendChild(section);
const sourceDialog=document.createElement('dialog');sourceDialog.id='bio-source-dialog';sourceDialog.className='bio-source-dialog';sourceDialog.innerHTML='<div class="dialog-top"><span class="small-label">这一段，来自哪里</span><button id="bio-close-source" class="close-dialog" aria-label="关闭来源">×</button></div><h2 id="bio-source-title">资料来处</h2><div id="bio-source-content"></div><p class="fine-note" id="bio-source-context">这里只列本人记录。文档中的计划、一次回忆和已完成事件各按资料本意呈现；不把资料出现时间自动当作事件发生时间。</p>';
document.body.appendChild(sourceDialog);
function openSources(ids){const projection=yearRecord(state.year).mode==='projection';$('#bio-source-title').textContent=projection?'过去母题来处':'资料来处';$('#bio-source-context').textContent=projection?'以下本人记录来自过去，只提供偏好、矛盾与创作母题，不是未来史料，也不能证明本章场景已经发生。':'这里只列本人记录。文档中的计划、一次回忆和已完成事件各按资料本意呈现；不把资料出现时间自动当作事件发生时间。';state.sourceIds=[...new Set(A(ids).map(String))];$('#bio-source-content').innerHTML=state.sourceIds.map(id=>{const s=sourceById(id);if(!s)return`<div class="bio-source-item"><h3>引用 ${E(id)}</h3><p>这个来源尚未随预览数据装载，先保留为待核对引用。</p></div>`;const safeUrl=typeof s.url==='string'&&/^https?:\/\//i.test(s.url)?s.url:null;return`<div class="bio-source-item"><div class="bio-source-type">${E(sourceType(s.type))}${s.date?` · ${E(s.date)}`:''}</div><h3>${E(s.title||s.id)}</h3>${s.note?`<p>${E(s.note)}</p>`:''}${safeUrl?`<a href="${E(safeUrl)}" target="_blank" rel="noopener noreferrer">打开原始记录 ↗</a>`:'<p class="bio-source-unlinked">未附私密原文。保留来源标题、日期、说明与编号供核对。</p>'}<small>来源编号 ${E(s.id)}</small></div>`;}).join('');if(!sourceDialog.open)sourceDialog.showModal();}
function volumes(){const result=[];for(let from=2000;from<=2100;from+=10){const to=Math.min(from+9,max),list=years.filter(year=>year>=from&&year<=to);if(list.length)result.push({from,to,list});}return result;}
function renderShelf(){const B=data();$('#bio-library-title').textContent=B.meta?.title||'此生';$('#bio-library-subtitle').textContent=B.meta?.subtitle||'从记录出发，让未写之处继续留白。';$('#bio-publication-label').textContent=isPrivatePreview()?'私密预览 · 个人资料与叙事分层':'人生传记 · 个人记录与叙事分层';$('#bio-cutoff').textContent=`资料截点 ${B.meta?.cutoff||'2026-11-06'}${isPrivatePreview()?' · 未发布':''}`;$('#bio-year-select').innerHTML=years.map(year=>`<option value="${year}" ${year===state.year?'selected':''}>${year} · ${E(labels[yearRecord(year).mode]||'整理中')}</option>`).join('');$('#bio-volume-list').innerHTML=volumes().map((volume,index)=>{const list=volume.list.filter(year=>state.filter==='all'||['recorded','present'].includes(yearRecord(year).mode));if(!list.length)return'';return`<details class="bio-volume" ${volume.list.includes(state.year)||state.filter==='recorded'?'open':''}><summary><span>${String(index+1).padStart(2,'0')}</span>${volume.from}—${volume.to}<small>${list.length} 章</small></summary><div>${list.map(year=>{const b=yearRecord(year);return`<button data-bio-year="${year}" class="bio-year-spine ${year===state.year?'active':''}" ${year===state.year?'aria-current="page"':''}><span class="bio-mode-dot ${E(b.mode)}"></span><strong>${year}</strong><span>${E(b.title||'这一年的一页')}</span></button>`;}).join('')}</div></details>`;}).join('')||'<p class="bio-empty-shelf">尚未载入有来源的年份；全部年份仍可从下拉框进入。</p>';$$('[data-bio-year]').forEach(button=>button.addEventListener('click',()=>open(button.dataset.bioYear)));$$('[data-bio-filter]').forEach(button=>button.classList.toggle('active',button.dataset.bioFilter===state.filter));$('#bio-reader-position').textContent=`${state.year} / ${labels[yearRecord(state.year).mode]||'整理中'}`;}
function renderFacts(b){if(b.mode==='projection'&&!A(b.anchoredFacts).length)return'<section class="bio-facts-section bio-projection-facts"><h3>未来推演 · 尚未发生</h3><p class="bio-gap-note">这一年尚未发生，本章为情境推演，没有当年事实锚点。引用的过去记录只提供创作母题，不是未来史料。</p></section>';return renderRecordedFacts(b);}
function renderRecordedFacts(b){if(!A(b.anchoredFacts).length)return`<section class="bio-facts-section"><h3>这章用到的事实锚点</h3><p class="bio-gap-note">当前没有列出的个人事实，不据此推断这一年平静、没有变化或没有重要的人。</p></section>`;return`<section class="bio-facts-section"><h3>这章用到的事实锚点</h3><div class="bio-fact-list">${b.anchoredFacts.map((fact,index)=>{const astro=valid(fact.astroYear)?rawYear(fact.astroYear):null;return`<div class="bio-fact" id="bio-fact-${index}"><time>${E(fact.date||'时间待补')}</time><div><h4>${E(fact.label)}</h4><p>${E(fact.detail||'')}</p><div class="bio-fact-meta"><span>${E(certaintyLabel(fact.certainty))}</span>${sourceButtons(fact.sourceIds,'事实来处')}</div>${astro?`<button class="bio-astro-link ${Number(fact.astroYear)!==b.year?'cross-year':''}" data-bio-astro="${astro.year}">对应 ${astro.year}${E(astro.stem)}${E(astro.branch)}流年 · 单独自查 ↗</button>`:'<small class="bio-unbound-fact">仅按公历收录；未在此绑定某一流年。</small>'}</div></div>`;}).join('')}</div></section>`;}
function renderEchoes(b){if(!A(b.echoes).length)return'';return`<section class="bio-echoes-section"><h3>跨过年份，仍在继续的线</h3>${b.echoes.map(echo=>{const thread=A(data().threads).find(t=>t.id===echo.threadId),related=years.filter(year=>year!==b.year&&A(yearRecord(year).echoes).some(e=>e.threadId===echo.threadId));return`<div class="bio-echo"><span>${E(thread?.title||'一条仍在延续的线')}</span><p>${E(echo.text||thread?.question||'')}</p>${thread?.motif?`<small>反复出现的物件 / ${E(thread.motif)}</small>`:''}<div class="bio-echo-years">${valid(echo.fromYear)?`<button data-bio-year="${Number(echo.fromYear)}">回读 ${Number(echo.fromYear)} ↗</button>`:''}${related.filter(year=>year!==Number(echo.fromYear)).sort((a,c)=>Math.abs(a-b.year)-Math.abs(c-b.year)).slice(0,4).map(year=>`<button data-bio-year="${year}">${year} ↗</button>`).join('')}</div></div>`;}).join('')}</section>`;}
function renderChoiceSection(b){const y=G.getYear(b.year),selected=G.choiceForYear(b.year),chosen=y.choices.find(c=>c.id===selected);const historical=['recorded','gap'].includes(b.mode);return`<section class="bio-choice-section" id="bio-choice-section"><div class="bio-section-label">${historical?'回看中的另一条路':'把这一页带进一次选择'}</div><h3>${historical?'如果当时，换一种走法？':'下一步，你更愿意怎么走？'}</h3><p class="bio-choice-boundary">${historical?'以下是反事实游戏支线，保留原有资料中的经历，不改写已经发生的事。':'以下是情境演练，不作为已经发生的个人经历。'}选择只进入模拟行囊。</p><div class="bio-choice-grid">${y.choices.map((choice,index)=>`<button data-bio-choice="${E(choice.id)}" class="${selected===choice.id?'selected':''}" aria-pressed="${selected===choice.id}"><small>0${index+1}</small><strong>${E(choice.label)}</strong><p>${E(choice.story)}</p></button>`).join('')}</div><div class="bio-choice-result" ${chosen?'':'hidden'}>${chosen?`<span>游戏支线 · ${E(chosen.label)}</span><p>${E(chosen.outcome||'这次选择已进入你的模拟行囊。')}</p>`:''}</div></section>`;}
function renderArticle(){const b=yearRecord(state.year),mode=labels[b.mode]||'整理中',allSources=[...new Set([...A(b.sourceIds),...A(b.scenes).flatMap(s=>A(s.sourceIds)),...A(b.anchoredFacts).flatMap(f=>A(f.sourceIds))])];const modeCopy={recorded:'从个人记录里整理出的这一年。场景中仍有叙事连接，逐段标明。',gap:'这一年的个人资料尚有缺口。留白被保留，情境补写不会冒充经历。',present:`记录截至 ${data().meta?.cutoff||'2026-11-06'}；这一年仍在进行，之后的部分不提前写成事实。`,projection:'从已知背景出发的一种未来情境。具体人物、场景和后果均非已发生事实。'}[b.mode]||'';
$('#bio-article').innerHTML=`<header class="bio-chapter-header"><div class="bio-chapter-meta"><span class="bio-mode-badge ${E(b.mode)}">${E(mode)}</span><span>公历 ${b.year} 年</span><span>生日满 ${b.year-2000} 周岁</span></div><div class="bio-year-number">${b.year}</div><h1>${E(b.title||'这一年的一页')}</h1>${b.logline?`<p class="bio-logline">${E(b.logline)}</p>`:''}<p class="bio-mode-explainer">${E(modeCopy)}</p><p class="bio-calendar-fixed">传记按公历归年；命盘按农历流年，日期可能跨层。</p>${sourceButtons(allSources,b.mode==='projection'?'查看过去母题来处':'查看这一章的资料')}</header>${renderStarReference(b.year)}<figure class="bio-chapter-art"><button data-bio-comic-year="${b.year}" aria-label="进入${b.year}年漫画"><img src="${E(b.image||`assets/years/${b.year}.jpg`)}" alt="${E(b.illustrationNote||(b.image?'依据本人记录的艺术化情境图，非现场照片':'初版命盘主题情境图，非真实经历还原'))}" decoding="async"></button><figcaption>${E(b.illustrationNote||(b.image?'本章艺术化情境图，非现场照片':'初版命盘主题情境图，非真实经历还原'))}<span>点图进入漫画 ↗</span></figcaption></figure>${b.opening?`<div class="bio-opening">${E(b.opening)}</div>`:''}<div class="bio-scenes">${A(b.scenes).map((scene,index)=>`<section class="bio-scene" data-scene-kind="${E(scene.kind||'reconstructed')}"><div class="bio-scene-kicker"><span>场景 ${String(index+1).padStart(2,'0')}</span><b class="${E(scene.kind||'reconstructed')}">${E(sceneLabels[scene.kind]||'叙事补写')}</b></div><h2>${E(scene.title||'这一年的一个片段')}</h2>${A(scene.prose).map(prose=>`<p>${E(prose)}</p>`).join('')}<div class="bio-scene-sources">${sourceButtons(scene.sourceIds,b.mode==='projection'?'这段的过去母题':'这段的来处')}${!A(scene.sourceIds).length?'<small>这段未列单独引用；请结合其叙事标记阅读。</small>':''}</div></section>`).join('')||'<div class="bio-unwritten-page"><span>这一页，暂时留白。</span><p>资料到来之前，不替你补上人物、地点或转折。</p></div>'}</div>${b.closing?`<div class="bio-closing">${E(b.closing)}</div>`:''}${renderFacts(b)}${renderEchoes(b)}${b.bridge?`<div class="bio-next-thread"><span>带到下一页</span><p>${E(b.bridge)}</p></div>`:''}${renderChoiceSection(b)}<section class="bio-chapter-sources"><details><summary>${b.mode==='projection'?'本章的过去母题':'本章资料索引'} <span>${allSources.length} 条</span></summary>${b.mode==='projection'?'<p class="bio-projection-source-note">这些过去的本人记录只提供创作母题，不证明未来场景发生。</p>':''}${allSources.map(id=>{const s=sourceById(id);return`<button class="bio-source-index-item" data-bio-sources="${E(id)}"><span>${E(sourceType(s?.type))}</span><strong>${E(s?.title||'待装载引用 '+id)}</strong><small>${E(s?.date||'')}</small></button>`;}).join('')||'<p>尚无列出的本人记录；未用转载文献补作个人经历。</p>'}</details></section><nav class="bio-page-turns" aria-label="传记前后年"><button id="bio-prev-year" ${b.year===min?'disabled':''}><small>${b.year===min?'书页起点':'上一章'}</small><strong>${b.year===min?'从这里开始':'← '+(b.year-1)}</strong></button><span>阅读范围的一页<br>随时可以换一种读法</span><button id="bio-next-year" ${b.year===max?'disabled':''}><small>${b.year===max?'书页边界':'下一章'}</small><strong>${b.year===max?'仍可重访任一年':(b.year+1)+' →'}</strong></button></nav>`;
bindArticle();}
function bindArticle(){$$('#bio-article [data-bio-comic-year]').forEach(button=>button.addEventListener('click',()=>G.enterYear(Number(button.dataset.bioComicYear))));$$('#bio-article [data-bio-year]').forEach(button=>button.addEventListener('click',()=>open(button.dataset.bioYear)));$$('#bio-article [data-bio-sources]').forEach(button=>button.addEventListener('click',()=>openSources(button.dataset.bioSources.split('|'))));$$('[data-bio-astro]').forEach(button=>button.addEventListener('click',()=>G.inspectYear(Number(button.dataset.bioAstro))));$$('[data-bio-choice]').forEach(button=>button.addEventListener('click',()=>{G.chooseForYear(state.year,button.dataset.bioChoice);refreshChoices();}));$('#bio-prev-year')?.addEventListener('click',()=>open(state.year-1));$('#bio-next-year')?.addEventListener('click',()=>open(state.year+1));}
function refreshChoices(){if(section.hidden)return;const old=$('#bio-choice-section');if(!old)return;old.outerHTML=renderChoiceSection(yearRecord(state.year));$$('[data-bio-choice]').forEach(button=>button.addEventListener('click',()=>{G.chooseForYear(state.year,button.dataset.bioChoice);refreshChoices();}));}
function open(value,options={}){if(!valid(value))return;state.year=Number(value);state.shelf=false;section.classList.remove('shelf-open');$('#bio-shelf-toggle').setAttribute('aria-expanded','false');G.showScreen('biography');G.markRead(state.year);renderShelf();renderArticle();history.replaceState(null,'',`#biography-${state.year}`);try{localStorage.setItem(BOOKMARK,JSON.stringify({year:state.year}));}catch(_){}if(options.scroll!==false)window.scrollTo({top:0,behavior:'instant'});}
window.CISHENG_BIOGRAPHY={open,currentYear:()=>state.year,openSources};
$('#nav-biography').addEventListener('click',()=>open(state.year));$('#bio-year-select').addEventListener('change',event=>open(event.target.value));$('#bio-shelf-toggle').addEventListener('click',()=>{state.shelf=!state.shelf;section.classList.toggle('shelf-open',state.shelf);$('#bio-shelf-toggle').setAttribute('aria-expanded',String(state.shelf));});$('#bio-return-cover').addEventListener('click',()=>{G.showScreen('cover');history.replaceState(null,'','#cover');});$('#bio-to-comic').addEventListener('click',()=>G.enterYear(state.year));$('#bio-to-chart').addEventListener('click',()=>G.inspectYear(state.year));$$('[data-bio-filter]').forEach(button=>button.addEventListener('click',()=>{state.filter=button.dataset.bioFilter;renderShelf();}));$('#bio-close-source').addEventListener('click',()=>sourceDialog.close());sourceDialog.addEventListener('click',event=>{if(event.target===sourceDialog){const r=sourceDialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)sourceDialog.close();}});document.addEventListener('cisheng:progress',refreshChoices);document.addEventListener('keydown',event=>{if(section.hidden||$$('dialog[open]').length||/INPUT|SELECT|TEXTAREA|BUTTON|A|SUMMARY/.test(event.target.tagName)||event.metaKey||event.ctrlKey||event.altKey)return;if(event.key==='ArrowLeft'){event.preventDefault();open(state.year-1);}else if(event.key==='ArrowRight'){event.preventDefault();open(state.year+1);}});window.addEventListener('hashchange',()=>{const match=location.hash.match(/^#biography-(\d{4})$/);if(match&&valid(match[1]))open(match[1]);});
const route=location.hash.match(/^#biography-(\d{4})$/);if(route&&valid(route[1]))open(route[1]);else if(!location.hash)open(state.year);
})();
